  result: 'None. Entering a destination persists nothing.',
  auth: { basis: 'ACTIVE_MEMBERSHIP_NAVIGATION', kernel: [], req: 'A live membership in the active organization. The entry is not authority over any resource behind it.', recusal: RECUSAL.NAVIGATION },
  audit: ['AUDIT_NONE_NONSENSITIVE_VIEW', 'No audit record beyond request logging. Reads of case data inside the destination follow the audit class of the action that performs them.'],
