const deny = (n, title, desc, prohibited, evidence, rel = []) => ({
  id: `STW-DENY-${String(n).padStart(2, '0')}`, kind: 'DENIAL', title,
  desc, actor: 'A person who holds only the steward role', trigger: `A steward attempts ${prohibited}.`,
  resource: prohibited,
  pre: ['The steward has no live relationship, mandate, designation or grant that names this resource and action.'],
  act: 'No action is permitted. The attempt is refused and recorded.',
  result: 'None. Nothing is written except the refusal record.',
  auth: { basis: 'ROLE_ELIGIBILITY_ONLY', kernel: [], req: 'The steward role is eligibility only. This contract states what the role never grants, so a later change cannot add it silently.', recusal: RECUSAL.CASE },
  audit: ['AUDIT_DENIAL_RECORDED', 'The refusal is recorded as security evidence.'],
  priv: ['PRIV_PRIVILEGED_EXCLUDED', 'Nothing is disclosed by the refusal.'],
  ui: 'The steward is told the action is not permitted and, where one exists, the request path.',
  deny: ['KERNEL_DENY_403', 'The refusal is the contract. A steward who needs the power requests it through the institution.'],
  impl: { status: 'SOURCE_PRESENT', routes: [A('lib/authority/policies/case.ts')], cap: 'UE-CAP-I-001', note: 'The kernel case policy refuses these without a live source of authority. Conformance has not been checked end to end.' },
  rel, evidence, adopt: [], design: 'A denial contract. It exists so the absence of a power is a recorded decision.',
})

